// Medidor de corriente con el sensor ACS712 (modelo de 5 A)
const int SENSOR = A0;        // OUT del sensor
const int ZUMBADOR = 8;
const int LED_ALERTA = 9;
const float SENSIBILIDAD = 0.185;   // voltios por cada amperio
const float LIMITE = 2.0;           // amperios para dar la alarma

void setup() {
  Serial.begin(9600);
  pinMode(ZUMBADOR, OUTPUT);
  pinMode(LED_ALERTA, OUTPUT);
}

void loop() {
  int lectura = analogRead(SENSOR);          // 0 a 1023 (512 = sin corriente)
  float voltaje = lectura * 5.0 / 1023.0;
  float corriente = (voltaje - 2.5) / SENSIBILIDAD;

  Serial.print("Corriente: ");
  Serial.print(corriente, 2);
  Serial.println(" A");

  if (abs(corriente) > LIMITE) {
    digitalWrite(LED_ALERTA, HIGH);
    tone(ZUMBADOR, 1500, 150);
  } else {
    digitalWrite(LED_ALERTA, LOW);
  }
  delay(500);
}

// Timbre automático escolar (versión Arduino Uno para Banco Arduino)
// Reloj DS3231 + pantalla OLED + relé + 5 botones
#include <Wire.h>
#include <RTClib.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

RTC_DS3231 rtc;                               // SDA en A4, SCL en A5
Adafruit_SSD1306 pantalla(128, 64, &Wire, -1);

const int BTN_MENU = 2;
const int BTN_SUBIR = 3;
const int BTN_BAJAR = 4;
const int BTN_OK = 5;
const int BTN_TIMBRE = 6;   // timbre manual
const int RELE = 7;         // activa el timbre de 110 V

// Horarios: hora, minuto, días (1 = suena ese día) y segundos que suena
const int TOTAL = 6;
int horaH[TOTAL] = {6, 9, 10, 12, 12, 0};
int horaM[TOTAL] = {30, 30, 0, 0, 30, 0};
int dur[TOTAL] = {5, 3, 3, 5, 8, 3};
String nombre[TOTAL] = {"Entrada", "Descanso", "Fin descanso", "Almuerzo", "Salida", "Prueba"};
bool usado[TOTAL] = {true, true, true, true, true, false};   // el 6 es para la prueba
// Días de la semana: Dom Lun Mar Mie Jue Vie Sab
bool lunAVie[7] = {false, true, true, true, true, true, false};

String DIAS[7] = {"Dom", "Lun", "Mar", "Mie", "Jue", "Vie", "Sab"};

bool sonando = false;
unsigned long sonarHasta = 0;
int ultimoMinuto = -1;
bool silencioHoy = false;
int diaSilencio = -1;
int pantallaActual = 0;      // 0 hora, 1 horarios de hoy, 2 silenciar hoy, 3 probar timbre, 4 prueba en 1 min
int desplazar = 0;
unsigned long ultimaTecla = 0;
bool antes[5] = {true, true, true, true, true};
int pinesBoton[5] = {2, 3, 4, 5, 6};

String dos(int n) {
  if (n < 10) return "0" + String(n);
  return String(n);
}

void tocar(int segundos, String quien) {
  sonando = true;
  sonarHasta = millis() + segundos * 1000;
  Serial.print("TIMBRE: ");
  Serial.print(quien);
  Serial.print(" (");
  Serial.print(segundos);
  Serial.println(" s)");
}

bool suenaHoy(int i, int dia) {
  if (!usado[i]) return false;
  if (i == 5) return true;          // la prueba suena cualquier día
  return lunAVie[dia];
}

void revisarHorarios(DateTime t) {
  int minutoActual = t.hour() * 60 + t.minute();
  if (minutoActual == ultimoMinuto) return;
  ultimoMinuto = minutoActual;
  if (silencioHoy && diaSilencio == t.day()) return;
  for (int i = 0; i < TOTAL; i++) {
    if (suenaHoy(i, t.dayOfTheWeek()) && horaH[i] == t.hour() && horaM[i] == t.minute()) {
      tocar(dur[i], nombre[i]);
      if (i == 5) usado[5] = false;
      return;
    }
  }
}

String proximo(DateTime t) {
  if (silencioHoy && diaSilencio == t.day()) return "Silenciado hoy";
  int ahora = t.hour() * 60 + t.minute();
  int mejor = -1;
  int mejorMin = 9999;
  for (int i = 0; i < TOTAL; i++) {
    int m = horaH[i] * 60 + horaM[i];
    if (suenaHoy(i, t.dayOfTheWeek()) && m > ahora && m < mejorMin) {
      mejor = i;
      mejorMin = m;
    }
  }
  if (mejor < 0) return "Manana " + dos(horaH[0]) + ":" + dos(horaM[0]);
  return dos(horaH[mejor]) + ":" + dos(horaM[mejor]) + " " + nombre[mejor];
}

int leerBoton() {
  for (int b = 0; b < 4; b++) {
    bool ahora = digitalRead(pinesBoton[b]);
    if (ahora != antes[b]) {
      antes[b] = ahora;
      if (ahora == LOW) return b;
    }
  }
  return -1;
}

void manejar(int b, DateTime t) {
  ultimaTecla = millis();
  if (b == 0) {                                   // MENU
    pantallaActual = (pantallaActual + 1) % 5;
    desplazar = 0;
    return;
  }
  if (pantallaActual == 1 && b == 1 && desplazar > 0) desplazar--;
  if (pantallaActual == 1 && b == 2 && desplazar < TOTAL - 1) desplazar++;
  if (pantallaActual == 2 && b == 3) {            // OK: silenciar hoy
    silencioHoy = !silencioHoy;
    diaSilencio = t.day();
    Serial.println(silencioHoy ? "Timbre silenciado por hoy" : "Timbre activado");
  }
  if (pantallaActual == 3 && b == 3) tocar(3, "Prueba manual");
  if (pantallaActual == 4 && b == 3) {            // OK: programa una prueba en 1 minuto
    horaH[5] = t.hour();
    horaM[5] = t.minute() + 1;
    if (horaM[5] == 60) {
      horaM[5] = 0;
      horaH[5] = (horaH[5] + 1) % 24;
    }
    usado[5] = true;
    Serial.println("Prueba programada a las " + dos(horaH[5]) + ":" + dos(horaM[5]));
  }
}

void dibujar(DateTime t) {
  pantalla.clearDisplay();
  pantalla.setTextColor(SSD1306_WHITE);
  pantalla.setTextSize(1);
  if (pantallaActual == 0) {
    pantalla.setTextSize(2);
    pantalla.setCursor(16, 0);
    pantalla.print(dos(t.hour()) + ":" + dos(t.minute()) + ":" + dos(t.second()));
    pantalla.setTextSize(1);
    pantalla.setCursor(0, 20);
    pantalla.print(DIAS[t.dayOfTheWeek()] + " " + dos(t.day()) + "/" + dos(t.month()) + "/" + String(t.year()));
    pantalla.setCursor(0, 36);
    if (sonando || digitalRead(BTN_TIMBRE) == LOW) pantalla.print("** TIMBRANDO **");
    else pantalla.print("Proximo timbre:");
    pantalla.setCursor(0, 48);
    pantalla.print(proximo(t));
  } else if (pantallaActual == 1) {
    pantalla.print("Horarios (L-V):");
    int fila = 0;
    for (int i = desplazar; i < TOTAL && fila < 5; i++) {
      if (!usado[i]) continue;
      pantalla.setCursor(0, 12 + fila * 10);
      pantalla.print(dos(horaH[i]) + ":" + dos(horaM[i]) + " " + nombre[i]);
      fila++;
    }
  } else if (pantallaActual == 2) {
    pantalla.print("Silenciar hoy:");
    pantalla.setTextSize(2);
    pantalla.setCursor(0, 18);
    pantalla.print((silencioHoy && diaSilencio == t.day()) ? "SI" : "NO");
    pantalla.setTextSize(1);
    pantalla.setCursor(0, 50);
    pantalla.print("OK = cambiar");
  } else if (pantallaActual == 3) {
    pantalla.print("Probar timbre");
    pantalla.setCursor(0, 24);
    pantalla.print(sonando ? "Sonando..." : "OK = tocar 3 s");
  } else {
    pantalla.print("Prueba de horario");
    pantalla.setCursor(0, 20);
    pantalla.print("OK = timbre en 1 min");
    if (usado[5]) {
      pantalla.setCursor(0, 40);
      pantalla.print("Sonara a las " + dos(horaH[5]) + ":" + dos(horaM[5]));
    }
  }
  pantalla.display();
}

void setup() {
  Serial.begin(9600);
  for (int b = 0; b < 5; b++) pinMode(pinesBoton[b], INPUT_PULLUP);
  pinMode(RELE, OUTPUT);
  digitalWrite(RELE, LOW);
  if (!rtc.begin()) Serial.println("No encuentro el reloj DS3231");
  pantalla.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  Serial.println("Timbre automatico listo");
  Serial.println("MENU cambia de pantalla, OK confirma, TIMBRE suena mientras lo presionas");
}

void loop() {
  DateTime t = rtc.now();
  revisarHorarios(t);

  if (sonando && millis() > sonarHasta) {
    sonando = false;
    Serial.println("Timbre apagado");
  }
  bool manual = digitalRead(BTN_TIMBRE) == LOW;
  digitalWrite(RELE, (sonando || manual) ? HIGH : LOW);

  int b = leerBoton();
  if (b >= 0) manejar(b, t);
  if (pantallaActual != 0 && millis() - ultimaTecla > 30000) pantallaActual = 0;

  dibujar(t);
  delay(100);
}
